def get_prime_exponents(n):
    if n == 1: return []
    d, temp, exponents = 2, n, []
    while d * d <= temp:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                count += 1
                temp //= d
            exponents.append(count)
        d += 1
    if temp > 1: exponents.append(1)
    return sorted(exponents)

solutions = {1}
for a in range(1, 100):
    for b in range(a, 100):
        n = (12 * a + 1) * (12 * b + 1)
        if get_prime_exponents(n) == [a, b]:
            solutions.add(n)
print(solutions)

